parameters.jsCode:
// ---- the in-200 retry gate, for every provider that answers "failed" with HTTP 200 (R18 / R19, 2026-10-14, FIX_PLAN §3.12) ----
// n8n's `retryOnFail` only fires when a node FAILS. DataForSEO answers a dead task with HTTP 200 and `status_code` 40101
// ("Internal SE Server Error."), Google's URL Inspection answers HTTP 200 with an `error` object ("Internal error
// encountered."): both look like success to n8n, so the run spent the money, got nothing, and carried on.
//   Until 2026-10-14 the only gate of this kind was `AI_Retry_Requests.js` (the AI paths) and the 50000-only IF of build
// section 25, which is why execution 549 billed `SERP Top 10` and `Facts SERP` for two 40101 answers, never re-sent them, and
// planned, scored ("winnable 68") and wrote a page on a results page nobody had seen; and why the technical audit of execution
// 550 lost 31 of 45 URL inspections and reported the 14 that answered as an improvement.
//   This kit is that one rule. Two halves, and the second matters more:
//     1. `RT.dfs` / `RT.google` classify an answer; `RT.retryable` says whether sending it again can help (a transient error
//        can, a permission error or an exhausted quota cannot); `RT.plan` builds the second attempt and `RT.merge` puts its
//        answers in the failed ones' place.
//     2. `RT.stats` / `RT.evidence` / `RT.note` carry what was actually seen — asked, answered, failed, retried — into the
//        report, so evidence that is missing is marked `unavailable` and nothing downstream may score on it. `RT.comparable`
//        is the same idea for two runs: counts measured on samples of different sizes are not compared.
const RT = (() => {
  const S = (x) => String(x == null ? '' : x);
  const N = (x) => { const v = Number(x); return Number.isFinite(v) ? v : 0; };
  // an answer that can be different next time: the provider's own servers, a timeout, a rate limit. Never a wrong request.
  const TRANSIENT = /internal (?:se )?server error|internal error|server error|timeout|timed out|temporar|try again|unavailable|service unavailable|backend|deadline exceeded|connection|socket|econn|eai_again|rate limit|too many requests|\b(?:429|500|502|503|504)\b/i;
  const PERMANENT = /permission|forbidden|unauthor|invalid[_ ]grant|credential|not found|no search results|no access|invalid field|unknown field|unsupported|quota|resource_exhausted|insufficient funds|payment|balance/i;
  // R68 (2026-10-16, re-rating B-10): 40102 "No Search Results." is DataForSEO's FINAL answer that the search has no results — the Google
  // Business Profile lookup for "Tech& Dubai" in execs 595 / 641 — not a failure. It was neither TRANSIENT nor PERMANENT, so it counted as
  // retryable: *Fetch GBP (Retry)* re-sent it and paid $0.0054 for the same 40102 every audit. It is a valid empty answer now: never
  // re-sent, never counted as a failure (Entity_Check already reads it as "no listing"), and marked `empty` so a reader can tell.
  const NO_RESULTS = 40102;
  const errText = (e) => {
    if (!e) return '';
    if (typeof e === 'string') return e.slice(0, 200);
    const ctx = (e.context && e.context.data) || {};
    const inner = (ctx.error && typeof ctx.error === 'object') ? ctx.error : null;
    return S((inner && inner.message) || (ctx.error_description ? S(ctx.error || 'error') + ': ' + ctx.error_description : '') || e.message || e.description || e.status || JSON.stringify(e)).slice(0, 200);
  };
  const verdict = (why, code) => {
    const ok = !why;
    const perm = !ok && PERMANENT.test(why) && !TRANSIENT.test(why);
    return { ok, why: why || '', code: code || 0, retryable: !ok && !perm, permanent: perm };
  };
  // the reason a report prints is the provider's OWN message ("Internal SE Server Error.", "Invalid Field: target."), never our
  // paraphrase of it: it is what the owner would see in the provider's console, and it is what `retryable` is decided on.
  const said = (msg, code, dflt) => S(msg).trim() ? S(msg).trim().slice(0, 160) : (code ? dflt + ' (error ' + code + ')' : dflt);
  /** one DataForSEO answer (the whole envelope of a live endpoint). The same four cases AI_Retry_Requests.js has used since D19. */
  const dfs = (r) => {
    const res = r || {};
    if (res.error) return verdict(errText(res.error) || 'the request failed');
    if (N(res.status_code) === NO_RESULTS) return { ...verdict('', NO_RESULTS), empty: true, permanent: true, said: S(res.status_message) || 'No Search Results.' };
    if (N(res.status_code) >= 40000) return verdict(said(res.status_message, N(res.status_code), 'the search data provider reported an error'), N(res.status_code));
    if (!Array.isArray(res.tasks) || !res.tasks.length) return verdict('no answer from the search data provider');
    const t = res.tasks[0] || {};
    const code = N(t.status_code);
    if (!code) return verdict('no answer from the search data provider');
    if (code === NO_RESULTS || (code >= 40000 && /no search results/i.test(S(t.status_message))))
      return { ...verdict('', code), empty: true, permanent: true, said: S(t.status_message) || 'No Search Results.' };
    if (code >= 40000) return verdict(said(t.status_message, code, 'the search data provider reported an error'), code);
    if (code === 20000 && !((t.result || [])[0])) return verdict('the search data provider returned no result', code);
    return verdict('', code);
  };
  /** one Google API answer (URL Inspection, Search Analytics): an `error` object, or the field the caller expected missing. */
  const google = (r, expect) => {
    const res = r || {};
    if (res.error) return verdict(errText(res.error));
    const want = S(expect);
    if (want && !res[want]) return verdict('no ' + want + ' in the answer');
    return verdict('');
  };
  const check = (r, o) => { const opt = o || {}; return opt.api === 'google' ? google(r, opt.expect) : dfs(r); };
  /** [answers] -> [{ i, why, retryable }] for the ones that failed (same order as the requests). */
  const failures = (answers, o) => (answers || []).map((r, i) => ({ i, v: check(r, o) })).filter(x => !x.v.ok).map(x => ({ i: x.i, why: x.v.why, code: x.v.code, retryable: x.v.retryable, permanent: x.v.permanent }));
  /** the second attempt: the failed requests, once, newest rule first — never more than `max`, never a permanent failure. */
  const plan = (requests, answers, o) => {
    const opt = o || {};
    const max = opt.max == null ? 60 : opt.max;
    const fails = failures(answers, opt).filter(f => !opt.only || opt.only(requests[f.i], f));
    const retryable = fails.filter(f => f.retryable);
    const out = retryable.slice(0, max).map(f => ({ ...(requests[f.i] || {}), retry_of: f.i, retry_reason: f.why, is_retry: true }));
    return { items: out, failed: fails.length, retryable: retryable.length, skipped: Math.max(0, retryable.length - out.length),
      permanent: fails.filter(f => f.permanent).map(f => f.why).slice(0, 3), reasons: fails.map(f => f.why).slice(0, 5) };
  };
  /** the first answers with each retry's answer in the failed one's place (the retry's own failure keeps the first reason). */
  const merge = (answers, retryItems, retryAnswers, o) => {
    const out = (answers || []).slice();
    (retryItems || []).forEach((q, k) => {
      const i = Number(q && q.retry_of);
      const a = (retryAnswers || [])[k];
      if (!Number.isFinite(i) || a === undefined) return;
      if (check(a, o).ok) out[i] = a;
    });
    return out;
  };
  /** what was actually seen, in numbers a report can print. */
  const stats = (answers, o, retryItems, retryAnswers) => {
    const opt = o || {};
    const first = failures(answers, opt);
    const merged = merge(answers, retryItems, retryAnswers, opt);
    const after = failures(merged, opt);
    const asked = (answers || []).length;
    const retried = (retryItems || []).length;
    return { asked, answered: asked - after.length, failed: after.length, failed_first: first.length, retried,
      retry_answered: Math.max(0, first.length - after.length), reasons: [...new Set(after.map(f => f.why))].slice(0, 3), answers: merged };
  };
  /** the same, for a path that makes ONE call and has one retry node (the SERP / facts / keyword-data gates). */
  const one = (first, retry, o) => stats([first], o, retry == null ? [] : [{ retry_of: 0 }], retry == null ? [] : [retry]);
  /** F-SERP (2026-10-20): ONE call sent up to N times in a row (the head keyword's results page: first, retry, lighter last try).
   *  `attempts` is [first, second, third ...] in the order they were sent, `null` for an attempt that never ran. The answer is the
   *  first attempt that answered (later attempts only run when the earlier ones failed); when none did, the FIRST failure's reason is
   *  kept, as `one` keeps it. `attempts` / `answered_on` say how many were sent and which one answered (1-based, 0 = none). */
  const chain = (attempts, o) => {
    const made = (attempts || []).map((a, k) => ({ a, k })).filter(x => x.a != null);
    if (!made.length) return { asked: 1, answered: 0, failed: 1, failed_first: 1, retried: 0, retry_answered: 0, reasons: ['no answer'], answers: [{}], attempts: 0, answered_on: 0, reasons_by_attempt: [] };
    const verdicts = made.map(x => ({ k: x.k, a: x.a, v: check(x.a, o) }));
    const hit = verdicts.find(x => x.v.ok);
    const firstV = verdicts[0];
    return { asked: 1, answered: hit ? 1 : 0, failed: hit ? 0 : 1, failed_first: firstV.v.ok ? 0 : 1, retried: made.length - 1,
      retry_answered: hit && hit !== firstV ? 1 : 0, reasons: hit ? [] : [firstV.v.why || 'no answer'], answers: [hit ? hit.a : firstV.a],
      attempts: made.length, answered_on: hit ? hit.k + 1 : 0, reasons_by_attempt: verdicts.map(x => x.v.ok ? '' : x.v.why),
      retryable: hit ? false : verdicts[verdicts.length - 1].v.retryable };
  };
  /** one sentence about those numbers, in the words the reports already use. */
  const note = (s, what) => {
    const st = s || {}; const thing = S(what) || 'request';
    const plural = (n) => n === 1 ? thing : thing + 's';
    if (!st.asked) return '';
    if (!st.failed && !st.retried) return '';
    if (!st.failed) return st.failed_first + ' of ' + st.asked + ' ' + plural(st.asked) + ' failed and ' + (st.retry_answered === 1 ? 'the retry answered' : 'all ' + st.retry_answered + ' answered when they were sent again') + '.';
    const again = (st.attempts > 2 && st.asked === 1) ? 'sent ' + st.attempts + ' times' : 'sent again once';   // F-SERP: one call sent three times is not "sent again once"
    return st.failed + ' of ' + st.asked + ' ' + plural(st.asked) + ' could not be checked' + (st.retried ? ' (' + again + ', ' + st.retry_answered + ' answered)' : ' (no answer)')
      + (st.reasons.length ? ': ' + st.reasons.join('; ') : '') + '. Only the ' + st.answered + ' that answered are counted below.';
  };
  /** the evidence block a score may be refused on: `unavailable` means nobody saw it, twice. */
  const evidence = (what, s, extra) => {
    const st = s || {};
    const unavailable = !st.asked || st.answered === 0;
    return { what: S(what), asked: st.asked || 0, checked: st.answered || 0, failed: st.failed || 0, retried: st.retried || 0,
      retry_answered: st.retry_answered || 0, unavailable, partial: !unavailable && (st.failed || 0) > 0,
      error: (st.reasons || [])[0] || '', note: note(st, (extra && extra.unit) || 'request'), ...(extra || {}) };
  };
  /** two counts measured on samples of different sizes are not a change (R19): say the sample moved instead of printing a delta.
   *  `unit` names what the sample is made of ("pages" by default, "questions" for the AI panel, "sources" for a link snapshot). */
  const MAX_SAMPLE_DRIFT = 0.2;
  const comparable = (now, before, o) => {
    const opt = o || {};
    const tol = opt.tolerance == null ? MAX_SAMPLE_DRIFT : opt.tolerance;
    const unit = S(opt.unit);                     // named only where the caller said what the sample is made of
    const a = Number(now), b = Number(before);
    if (!Number.isFinite(a) || !Number.isFinite(b) || a <= 0 || b <= 0) return { comparable: false, why: 'how many ' + (unit || 'pages') + ' each number was measured on was not recorded', drift: null };
    const drift = Math.abs(a - b) / Math.max(a, b);
    if (drift > tol) return { comparable: false, drift: Math.round(drift * 100) / 100,
      why: 'the two counts were measured on different samples (' + b + (unit ? ' ' + unit : '') + ' then, ' + a + ' now), so they are not compared' };
    return { comparable: true, drift: Math.round(drift * 100) / 100, why: '' };
  };
  /** the other half of like for like (R20, B-L4 / B-L5, 2026-10-15): two figures produced by runs of a DIFFERENT KIND are not a
   *  change either. R20 was a health score chained across a technical audit and a full report; the same shape reaches the AI
   *  panel (a weekly check asks fewer engines than the monthly full one) and the link ledger (a free_only snapshot is built from
   *  a different set of sources than a paid one). `labels` turns the stored key into the words a customer reads. The guard is a
   *  CALL, never an inlined kit: lineage_lint.py looks for the prefixed call, which this file never writes, so a node cannot
   *  look guarded without using it. Keep it that way: build section 73 fails if this kit ever spells one of those calls out. */
  const likeForLike = (now, before, o) => {
    const opt = o || {}, lab = opt.labels || {};
    const a = S(now).trim().toLowerCase(), b = S(before).trim().toLowerCase();
    const what = S(opt.what) || 'these two figures';
    const name = (k) => S(lab[k]) || k;
    if (!a || !b) return { comparable: false, why: 'what kind of run produced ' + (b ? 'this figure' : 'the earlier figure') + ' was not recorded, so ' + what + ' are not compared', kind: a, kind_before: b };
    if (a !== b) return { comparable: false, kind: a, kind_before: b,
      why: 'the earlier figure came from ' + name(b) + ' and this one from ' + name(a) + ', which do not measure the same thing, so ' + what + ' are not compared' };
    return { comparable: true, why: '', kind: a, kind_before: b };
  };
  return { dfs, google, check, failures, plan, merge, stats, one, chain, note, evidence, comparable, likeForLike, errText, MAX_SAMPLE_DRIFT, TRANSIENT, PERMANENT, NO_RESULTS };
})();
const prev = $('Check Page Claims').first().json;
// R18 (2026-10-14): the keyword's own search data goes through the same gate — the retry's answer when it came, and an honest
// "could not be read" when neither attempt did (live 549: items_count 0 beside two failed SERP calls, and the run scored anyway).
const kdStats = RT.one((() => { try { return $('Keyword Data').first().json; } catch (e) { return $input.first().json || {}; } })(),
                       (() => { try { return $('Keyword Data (Retry)').first().json; } catch (e) { return null; } })());
const keyword_data_evidence = RT.evidence('search volume, difficulty and cost per click for this keyword', kdStats, { unit: 'request' });
const res = kdStats.answers[0] || {};
let site_authority = null;
try { const m = $('Site Authority Answers').first().json?.tasks?.[0]?.result?.[0]?.items?.[0]?.metrics?.organic; if (m) site_authority = { organic_keywords: m.count ?? 0, top3: (m.pos_1 || 0) + (m.pos_2_3 || 0), top10: (m.pos_1 || 0) + (m.pos_2_3 || 0) + (m.pos_4_10 || 0), est_monthly_traffic: Math.round(m.etv || 0) }; } catch (e) {}
const item = res.tasks?.[0]?.result?.[0]?.items?.[0] || null;

const info = item?.keyword_info || {};
const props = item?.keyword_properties || {};
const intent = item?.search_intent_info || {};
const links = item?.avg_backlinks_info || {};
const trend = info.search_volume_trend || {};

// Difficulty ko aam alfaaz mein
const kd = props.keyword_difficulty;
const kdLabel = kd == null ? 'Unknown'
  : kd < 30 ? 'Easy'
  : kd < 50 ? 'Medium'
  : kd < 70 ? 'Hard'
  : 'Very Hard';

const keyword_data = item ? {
  search_volume: info.search_volume ?? null,
  cpc: info.cpc ?? null,
  ads_competition: info.competition_level ?? null,
  keyword_difficulty: kd ?? null,
  difficulty_label: kdLabel,
  google_intent: intent.main_intent ?? null,
  trend_yearly_pct: trend.yearly ?? null,
  trend_quarterly_pct: trend.quarterly ?? null,
  monthly_trend: (info.monthly_searches || [])
    .slice(0, 12)
    .map(m => ({ month: `${m.year}-${String(m.month).padStart(2, '0')}`, searches: m.search_volume })),
  competitor_backlink_strength: {
    avg_referring_domains: links.referring_domains != null ? Math.round(links.referring_domains) : null,
    avg_backlinks: links.backlinks != null ? Math.round(links.backlinks) : null,
    avg_dofollow: links.dofollow != null ? Math.round(links.dofollow) : null
  }
} : {
  note: keyword_data_evidence.unavailable
    ? 'Search data for this keyword could not be read: ' + (keyword_data_evidence.error || 'no answer') + (kdStats.retried ? ' (the request was sent again once and failed again)' : '') + '. This is not "no demand": nothing was measured.'
    : 'Keyword data not available for this keyword/country'
};

// Competitors ka lamba content aage AI ko nahi chahiye, sirf summary
const competitors_summary = (prev.competitors || []).map(c => ({
  rank: c.rank,
  domain: c.domain,
  url: c.url,
  title: c.title,
  word_count: c.word_count,
  headings: c.headings
}));

return [{
  json: {
    ...prev,
    competitors: undefined,
    competitors_summary,
    keyword_data,
    keyword_data_evidence,
    site_authority
  }
}];

parameters.text:
=You are a senior SEO content strategist. Create a detailed content brief for a page that will outrank the current competitors, win the answer features, and convert the reader. The brief is the only instruction the writer gets, so be specific.

{{ ($json.style_guide || {}).prompt_block || '' }}

PAGE DETAILS
Target Keyword: {{ $json.keyword }} · Country: {{ $json.country }} · Language: {{ $json.language_name || 'English' }} ({{ $json.spelling }} spelling) · Currency: {{ $json.currency }}
Page Type: {{ $json.page_type }}{{ $json.page_notes ? ' (what the verdict asked for: ' + $json.page_notes + ')' : '' }} · Business goal: {{ $json.goal || 'leads' }} · Tone requested: {{ $json.tone || 'professional and direct' }}
Verdict on this keyword: {{ $json.verdict }} ({{ $json.verdict_score }}/100). {{ ($json.verdict_reasons || []).join(' ') }} {{ $json.recommended_page && $json.recommended_page !== $json.page_type ? 'Recommended page type instead: ' + $json.recommended_page + '.' : '' }}
{{ ($json.page_contract || {}).text || '' }}
{{ ($json.verdict_exclusions || []).length ? 'LEAVE OUT (the verdict on this keyword: these do not match what its buyers want; no section, heading or question about them): ' + $json.verdict_exclusions.map(e => e.topic).join('; ') + '.' : '' }}
Business: {{ $json.business || 'Not provided: write for a generic business of this type, naming no business detail, with no brackets' }}
Customers: {{ $json.audience || 'Not provided' }}
Website: {{ $json.domain || 'Not provided' }}
Main call to action: {{ $json.cta || 'not specified — choose the natural one for the goal' }}
{{ $json.existing_page ? 'EXISTING PAGE ON THIS TOPIC: ' + $json.existing_page.url + ' — this brief is for improving/rewriting that page; keep its URL, keep its real facts, and make the structure clearly better than the competitors.' : 'No existing page found for this keyword — this is a new page.' }}

FACTS ABOUT THE CLIENT (only these may be stated as true; anything business-specific that is not here is left out of the page and, when it would make the page stronger, asked in questions_for_client)
Given by the client: {{ $json.business_facts || 'none' }}
Site description: {{ JSON.stringify($json.site_description || {}) }}
Signals found on their pages: {{ JSON.stringify($json.client_signals || {}) }}
Their pages (excerpts): {{ ($json.client_pages || []).map(p => '[' + p.kind + '] ' + p.url + ': ' + p.text.slice(0, 1800)).join('\n\n') || 'none read' }}
{{ $json.angle_rules || '' }}

AUTHOR AND TRUST (E-E-A-T)
{{ $json.eeat_context || 'No author profile on file: plan no experience notes; put what you would ask the author in questions_for_client.' }}
Case studies on file (real proof you may cite; link a case study only when it has a URL):
{{ $json.proof_context || 'none recorded' }}
{{ $json.role_brief || '' }}
{{ $json.video_context || '' }}

KEYWORD DATA
{{ JSON.stringify($json.keyword_data, null, 1) }}

SEARCH RESULTS PAGE FEATURES
{{ JSON.stringify($json.serp_features, null, 1) }}

COMPETITOR ANALYSIS
{{ JSON.stringify($json.competitor_analysis, null, 1) }}

COMPETITOR PAGES (title, word count, headings)
{{ JSON.stringify($json.competitors_summary, null, 1) }}

TERMS THE TOP PAGES SHARE
{{ $json.term_digest || 'n/a' }}

COVERAGE TARGET (read off the best page in these results, not an average — it is the bar to clear, not a promise about rankings)
{{ $json.coverage_digest || 'n/a — no competitor page could be read for this keyword, so plan the coverage from the keyword data and the questions above' }}

VERIFIED FACTS WITH SOURCES (the only external numbers the writer may cite)
{{ ($json.facts_list || $json.facts || []).map(f => '- ' + f.claim + ' — ' + f.source + ' — ' + f.url).join('\n') || 'none found; the page carries no external number' }}

REAL PAGES ON THE USER'S WEBSITE (the ONLY URLs you may use for internal links)
{{ ($json.ladder_links || []).length ? 'KEYWORD LADDER: this page is rung ' + $json.ladder_rung + ' of a ladder of pages that climb towards "' + $json.ladder_head + '". The pages marked "ladder" in the list below belong to that ladder and are live: link to them with natural, descriptive anchors. Ladder pages that are not published yet are NOT in the list and must never be linked or invented' + (($json.planned_link_targets || []).length ? ' (' + ($json.planned_link_targets || []).map(l => '"' + (l.keyword || l.about || l.url) + '"').join(', ') + ' are still planned)' : '') + '.' : '' }}
{{ $json.ai_target ? 'AI ANSWER TARGET (plan the page to become the one AI assistants cite): buyers ask ChatGPT, Gemini, Perplexity, Copilot and Google\'s AI: "' + $json.ai_target.question + '". Today the answers do not name ' + ($json.domain || 'this business') + (($json.ai_target.competitors || []).length ? ' and name ' + $json.ai_target.competitors.join(', ') : '') + '. Before answering, the assistants search for: ' + (($json.ai_target.fanout || []).map(f => '"' + f + '"').join(', ') || 'n/a') + '. The pages they cite now: ' + (($json.ai_target.sources || []).map(x => (x.title || x.url) + ' — ' + x.url).join('; ') || 'n/a') + '. Requirements: ' + '(1) the H1 carries the question or its topic and the first 40-60 words after it answer the question directly (an assistant reads the first ~200 characters of a page); ' + '(2) one H2 phrased as a question for each search above that fits the topic, each answered in its first sentence; ' + '(3) a neutral comparison table of the options buyers weigh (criteria, who each option suits) — never rank this business first, show where it fits; ' + '(4) concrete figures with their source, preferring the official sources above; an expert quote placeholder for the author; ' + '(5) the follow-up questions as further question-style headings, each answered in 40-60 words (never an FAQ block: Google stopped showing FAQ rich results in May 2026); plan snippet_targets from the question and the searches.' + ($json.ai_target.kind === 'refresh' ? ' This is a REFRESH of the existing page: keep its URL and every true fact, add what is missing above and update every date and figure.' : '') : '' }}
{{ ($json.internal_link_candidates || []).length ? JSON.stringify(($json.internal_link_candidates || []).slice(0, 40), null, 1) : 'No sitemap could be read — return an empty internal_link_suggestions array.' }}

Return ONLY a valid JSON object (no markdown, no backticks, no extra text) in this exact structure:
{
  "meta_title": "Max 60 characters, keyword near the start, a specific benefit",
  "title_variants": ["2 alternative titles"],
  "meta_description": "120-155 characters, keyword + concrete benefit + call to action",
  "meta_variants": ["1 alternative description"],
  "slug": "short-url-slug",
  "h1": "",
  "primary_keyword": "",
  "secondary_keywords": ["5-8 related keywords to use naturally"],
  "target_audience": "who exactly, in one sentence",
  "audience_pain_points": ["3-5 pains in the reader's words"],
  "objections": ["3-5 doubts the reader has that the page must answer"],
  "search_intent": "",
  "tone": "",
  "reading_level": "e.g. busy business reader, grade 8-10",
  "target_word_count": 0,
  "answer_block": "A 40-70 word direct answer to the main question, written to be quoted by featured snippets and AI answers. No placeholders, no unverifiable numbers.",
  "information_gain": ["3-5 things this page will provide that no competitor does (from the analysis), each concrete enough to write"],
  "unique_angle": "",
  "outline": [
    { "h2": "", "purpose": "Why this section exists and what the reader can do after it", "key_points": ["", ""], "h3s": ["optional sub-headings"], "target_words": 0, "format": "prose | steps | checklist | table | comparison | example", "evidence": ["which verified fact or client fact to use here, or 'none' (then the section carries no number)"], "link_to": "hub pages only: the URL of the cluster page this section summarises and links to, else empty" }
  ],
  "snippet_targets": [{ "question": "exact question to use as an H2/H3", "answer": "40-60 word direct answer" }],
  "terms_to_use": [{ "term": "", "min_count": 1 }],
  "evidence_plan": [{ "fact": "", "source_url": "" }],
  "client_facts": ["facts from the client's pages/form the copy must use (name, services, locations, credentials, numbers)"],
  "experience_notes": ["0-4 experience passages the page may carry, each tied to a section and each taken ONLY from the client facts, the case studies or the author's credentials above (what is on file, said as it is on file). Never a first-person stance, process or promise that is not on file, never a bracket: when nothing is on file, leave this list empty and ask in questions_for_client"],
  "video_placement": "only when the page has a video: 'top' or the exact H2 it belongs under, else empty",
  "proof_elements": ["proof the page shows, ONLY from what is on file (a case study, a certification, a number the client gave); none when nothing is on file"],
  "questions_for_client": ["0-5 short questions whose answers would make this page stronger and that only the client can answer (a publishable result, a credential, how an engagement starts, a local detail); never something the facts, the site or a public source already answers, never SEO mechanics"],
  "gaps_to_cover": ["Competitor gaps this page must fill"],
  "entities_to_mention": [""],
  "comparison_table": { "title": "", "columns": [""], "rows_hint": "what the rows compare — criteria the reader can check for themselves (compliance, modules, effort, who it suits). Never a column or row that only a price or a timeline could fill unless those facts are on file above" },
  "internal_link_suggestions": [{ "anchor": "", "url": "must be one of the REAL PAGES above" }],
  "image_suggestions": [{ "placement": "hero | the exact H2 text the image belongs under", "purpose": "hero | diagram | screenshot | photo | chart | table", "subject": "what the image must show, specific enough for a designer or a stock search (no faces of real people, no competitor logos)", "alt_text": "what the image shows, naturally including the topic, under 125 characters, no 'image of'", "caption": "one line that adds information, or empty", "filename": "kebab-case-with-the-topic.webp" }],   // exactly 3: one hero (also the featured / Open Graph image) + two in-body images at the sections where a visual explains more than text
  "faqs": ["6-8 follow-up questions — reuse the People Also Ask questions where relevant; each becomes its own question-style heading answered in 40-60 words inside the section it belongs to, never a separate FAQ block"],
  "cta": "Main call to action for the page: an invitation to get in touch the way the client facts say (for example a consultation request). Never a deliverable, a timeline, a price or a result that is not on file",
  "voice_rules": ["3-5 concrete style rules for this brand and audience"]
}

RULES
- The structure must suit a {{ $json.page_type }}, not a blog post, unless the page type is Blog Post or Guide.
- target_word_count = the recommended_word_count from the competitor analysis (already clamped: service/landing pages 900-2,400, guides 1,200-3,000), or the number the verdict named above when it named one. {{ (($json.competitor_analysis || {}).length_band || {}).ok ? 'LENGTH BAND: ' + $json.competitor_analysis.length_band.basis + '. Plan anywhere inside ' + $json.competitor_analysis.length_band.low + '-' + $json.competitor_analysis.length_band.high + ' words (a number outside it is cut back to ' + $json.competitor_analysis.length_band.target_word_count + ', and the outline with it).' : 'Anything outside 10% of it is cut back to it, and the outline with it, so plan to the number.' }} The outline has 6-9 H2 sections whose target_words add up to this number. Depth beats breadth: fewer sections, each complete.
- Plan a page the writer can finish from the facts above, with no square brackets anywhere in it. A section that could only be written with figures nobody gave (prices, timelines, counts) is the wrong section: plan the qualitative answer instead. Methods, steps and checklists are planned as advice to the reader, never as what the business does unless the facts say so.
- Every item in content_gaps and information_gain_opportunities from the competitor analysis must be covered somewhere in the outline.
- Use question-style H2s where the People Also Ask data shows questions; put those questions in snippet_targets with a direct answer.
- terms_to_use: 12-20 terms from the shared-terms list that the page must use naturally, with a realistic minimum count. Choose enough of them to reach the coverage target above, and never at the cost of readable sentences: coverage comes from covering the subject, not from repeating words. Coverage is measured the same way on the draft and on the best page: a term counts once it appears. min_count is a writing guide (how often the subject naturally needs the word), never a quota: set it from what the page's length allows, not from the competitor's repetitions.
- Every subtopic in the COVERAGE TARGET block must be answered somewhere in the outline — as its own section or inside a related one, as far as it fits the page being written: the target page was chosen among results of this page's kind, but a heading that sells something, addresses a different audience (for example agencies reselling the service) or names another company is not a subtopic — leave it out. Our own structure, our own words and our own order: never copy that page's headings or sentences (the draft is checked for overlap against every competitor page read, and over 15% of identical 8-word runs fails the quality check).
- evidence_plan may ONLY contain facts from the VERIFIED FACTS list, copied exactly with their URL. Prefer the official, standards, research and major-press sources; use at most one page per vendor or agency blog on the whole page, and never for a market or compliance figure.
- internal_link_suggestions may ONLY use URLs from the REAL PAGES list (3-6 links). Never invent a URL.
- Do not copy competitor headings. Build a better, more complete structure.
- experience_notes: never invent an experience, client, number or result. Experience is what separates this page from AI-written competitors: tie each note to a real fact when one exists.
- A HUB PAGE, CASE STUDY or LOCAL PAGE block above overrides the section-count, length and internal-link-count rules where they conflict.
- Write in {{ $json.language_name || 'English' }} with {{ $json.spelling }} spelling.

