for (const r of RULES) {
  const hits = [];
  for (const p of pages) {
    const m = p.meta || {};
    let detail = '';
    try { detail = r.test(p, m, m.content || {}, p.page_timing || {}); } catch (e) { detail = ''; }
    if (detail) hits.push({ url: p.url, detail });
  }
  if (hits.length) {
    findings.push({
      category: r.cat, severity: r.sev, title: r.title, why: r.why, fix: r.fix,
