// ===== 3. Domain-level checks =====
const dc = di.checks || {};
const addDomain = (cond, flag, cat, sev, title, why, fix, evidence) => {
  // INVARIANTS rule 1 (2026-10-15): these seven findings shipped with an EMPTY evidence string — raised, scored and ranked
