const _ps47 = (((d.pagespeed || {}).rows) || []).filter(r => r && r.available !== false && r.score != null);
let _ages47 = null; try { _ages47 = ($('Domain Ages').first().json || {}).ages || null; } catch (e) { _ages47 = null; }
