</head><body>${d.result_html || '<p>No keyword ideas were generated.</p>'}${note}</body></html>`;

const safe = String(d.domain || 'business').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
