//   SRC.figures(text)   every figure with its position: percentages, currency amounts, magnitudes (k / m / bn), years, counts >= 1,000.
//                       Small bare numbers ("3 steps", "8 phases") are not claims and are never checked.
//   SRC.hasFigure(f, t) the same figure in the source text, in any format: separators, "m" / "million", "AED 50m" / "AED 50 million".
// Regex only: the n8n Code sandbox has no URL constructor.
const SRC = (() => {
  const TRACK = /^(?:utm_[a-z0-9_]*|srsltid|gclid|gbraid|wbraid|dclid|fbclid|msclkid|yclid|twclid|ttclid|igshid|mc_cid|mc_eid|_hsenc|_hsmi|hsa_[a-z0-9_]*|s_kwcid|vero_id|oly_enc_id|cmpid|mkt_tok|spm|scid|ref_src|pk_campaign|pk_kwd|piwik_campaign|at_medium|at_campaign)$/i;
  const host = (u) => { const m = String(u == null ? '' : u).trim().match(/^https?:\/\/(?:[^@\/?#]*@)?([^\/?#:]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };
  const clean = (u) => {
    const s = String(u == null ? '' : u).trim();
    if (!s || s.indexOf('?') < 0) return s;
    const h = s.indexOf('#'); const frag = h >= 0 ? s.slice(h) : ''; const noFrag = h >= 0 ? s.slice(0, h) : s;
    const q = noFrag.indexOf('?'); if (q < 0) return noFrag + frag;
    const kept = noFrag.slice(q + 1).split('&').filter(p => p && !TRACK.test(p.split('=')[0]));
    return noFrag.slice(0, q) + (kept.length ? '?' + kept.join('&') : '') + frag;
  };
  const key = (u) => clean(String(u == null ? '' : u)).toLowerCase().replace(/[#?].*$/, '').replace(/\/+$/, '');
  const PRIMARY = /(^|\.)(gov|edu|mil|int)$|(^|\.)(gov|edu|ac|mil)\.[a-z]{2,3}$|(^|\.)(europa\.eu|who\.int|oecd\.org|worldbank\.org|imf\.org|un\.org|unctad\.org|ilo\.org|wto\.org|iso\.org|w3\.org|ietf\.org|oasis-open\.org|gs1\.org|peppol\.eu|peppol\.org|openpeppol\.org|etsi\.org|cen\.eu|bis\.org|eurostat\.eu|u\.ae)$/i;
  const RESEARCH = /(^|\.)(statista\.com|gartner\.com|forrester\.com|idc\.com|mckinsey\.com|deloitte\.com|pwc\.com|kpmg\.com|ey\.com|accenture\.com|bcg\.com|bain\.com|hbr\.org|ibisworld\.com|grandviewresearch\.com|marketsandmarkets\.com|mordorintelligence\.com|nielsen\.com|pewresearch\.org|cbinsights\.com|statcounter\.com|similarweb\.com)$/i;
  const PRESS = /(^|\.)(reuters\.com|bloomberg\.com|bbc\.com|bbc\.co\.uk|nytimes\.com|wsj\.com|ft\.com|economist\.com|apnews\.com|cnbc\.com|theguardian\.com|forbes\.com|techcrunch\.com|zdnet\.com|arstechnica\.com|theregister\.com|gulfnews\.com|khaleejtimes\.com|thenationalnews\.com|arabianbusiness\.com|zawya\.com|bizjournals\.com)$/i;
  const VENDOR = /(^|\.)(microsoft\.com|oracle\.com|sap\.com|odoo\.com|zoho\.com|salesforce\.com|netsuite\.com|sage\.com|xero\.com|intuit\.com|quickbooks\.intuit\.com|google\.com|adobe\.com|aws\.amazon\.com|amazon\.com|ibm\.com|stripe\.com|shopify\.com|hubspot\.com|atlassian\.com|cloudflare\.com|mozilla\.org|developer\.mozilla\.org)$/i;
  const BLOGGY = /\/(?:blog|blogs|insights|resources|articles|news|post|posts|guides?)(?:\/|$)/i;
  const tier = (u) => {
    const h = host(u); if (!h) return 'weak';
    if (PRIMARY.test(h)) return 'primary';
    if (RESEARCH.test(h)) return 'research';
    if (PRESS.test(h)) return 'press';
    if (VENDOR.test(h)) return BLOGGY.test(String(u || '')) ? 'weak' : 'vendor';   // a vendor's own documentation is usable; its blog is not
    return 'weak';
  };
  const TIERS = { primary: 'official or standards body', research: 'research house', press: 'major press', vendor: 'vendor documentation', weak: 'no independent authority (vendor or agency blog, listicle, unknown site)' };
  const strong = (u) => tier(u) !== 'weak';
  // ---- figures ----
  const MAG = { k: 1e3, thousand: 1e3, m: 1e6, mn: 1e6, million: 1e6, bn: 1e9, b: 1e9, billion: 1e9, tn: 1e12, trillion: 1e12 };
  const CUR = '(?:AED|USD|SAR|QAR|KWD|BHD|OMR|EGP|PKR|INR|EUR|GBP|ZAR|Dhs?|SR|Rs\\.?|\\$|€|£|₹)';
  const NUM = '\\d[\\d,]*(?:\\.\\d+)?';
  const UNITS = '(?:thousand|trillion|million|billion|mn|bn|tn|k|m|b)';   // longest first: "1,802 million" must not match as "1,802 m"
  const UNIT = '(?:\\s?' + UNITS + '\\b)?';
  const FIG_RE = new RegExp('(' + [
    CUR + '\\s?' + NUM + UNIT,                                     // AED 50m, $1.2 billion
    NUM + '\\s?' + UNITS + '\\b\\s?' + CUR,                        // 50 million AED
    NUM + '\\s?(?:%|percent\\b|per cent\\b|percentage points?\\b)',  // 23%, 1.74 percent
    NUM + '\\s?' + UNITS + '\\b',                                  // 2.4 million
    '(?:19|20)\\d{2}(?![\\d-])',                                    // a year, not part of a longer number or a date range code
    '\\d{1,3}(?:,\\d{3})+(?:\\.\\d+)?',                             // 1,234 / 12,345.6
    '\\d{4,}(?:\\.\\d+)?'                                           // 25000
  ].join('|') + ')', 'gi');
  const valueOf = (raw) => {
    const s = String(raw == null ? '' : raw).trim().replace(/[.,;:]+$/, '');
    if (!s) return null;
    const low = s.toLowerCase();
    const digits = (low.match(new RegExp(NUM)) || [''])[0];
    const n = Number(digits.replace(/,/g, ''));
    if (!digits || !Number.isFinite(n)) return null;
    const mm = low.match(/\d\s*(k|mn|m|bn|b|tn)\b/) || low.match(/\b(thousand|million|billion|trillion)s?\b/);
    const mag = mm ? MAG[mm[1]] : 0;
    const pct = /%|percent|per cent/.test(low);
    return { raw: s, n, v: mag ? n * mag : n, pct, year: !mag && !pct && /^(?:19|20)\d{2}$/.test(digits) };
  };
  // every figure with where it sits, so the caller can bracket it in place
  // `raw` is the figure without its trailing punctuation, and `length` matches it, so a caller can replace it in place without eating the full stop
  const figures = (text) => { const out = []; for (const m of String(text == null ? '' : text).matchAll(FIG_RE)) { const f = valueOf(m[0]); if (f) out.push({ ...f, index: m.index, length: f.raw.length }); } return out; };
  // ---- R37 (2026-10-16, re-rating 2026-10-15): the SOURCE side reads numbers written in words, and a snippet cut before its unit ----
  // Live (exec 616) McKinsey's snippet read "Forty percent of respondents … report scaling AI agents, up from 27 ... Read more". The draft
  // quoted it exactly ("40% … up from 27%") and both figures were masked as "not carried": the matcher knew only digits, and the snippet
  // was cut before "percent". `spelled()` rewrites number words into digits ("Forty percent" -> "40 percent", "fifty million dirhams" ->
  // "50 million dirhams", "a third" -> "33.3 percent") on the text a figure is LOOKED UP in — never on the draft, whose figure positions the
  // caller brackets in place. `cutPct()` accepts a bare number that sits right where the snippet was cut ("27 ..." / "27…" / the end of
  // the text) only for a percentage, and only when the same excerpt states a percentage within the 240 characters before it: the number
  // itself must be there, and the unit it lost is the one the sentence was using. Nothing else is loosened: a number the excerpt does not
  // carry is still not carried, and a bare number in a COMPLETE sentence ("up from 27 respondents.") still vouches for nothing.
  const ONES = { zero: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12,
    thirteen: 13, fourteen: 14, fifteen: 15, sixteen: 16, seventeen: 17, eighteen: 18, nineteen: 19 };
  const TENS = { twenty: 20, thirty: 30, forty: 40, fifty: 50, sixty: 60, seventy: 70, eighty: 80, ninety: 90 };
  const NW = '(?:' + Object.keys(TENS).concat(Object.keys(ONES).sort((a, b) => b.length - a.length)).join('|') + '|hundred)';
  const NW_RUN = new RegExp('\\b' + NW + '(?:(?:[\\s-]+|\\s+and\\s+)' + NW + ')*\\b', 'gi');
  const FRACTIONS = [[/\b(?:a|one)[\s-]+half\b|\bhalf\s+of\b/gi, '50 percent'], [/\btwo[\s-]+thirds\b/gi, '66.7 percent'], [/\b(?:a|one)[\s-]+third\b/gi, '33.3 percent'],
    [/\bthree[\s-]+quarters\b/gi, '75 percent'], [/\b(?:a|one)[\s-]+quarter\b/gi, '25 percent']];
  const spelled = (text) => {
    let t = String(text == null ? '' : text);
    for (const fr of FRACTIONS) t = t.replace(fr[0], fr[1]);
    return t.replace(NW_RUN, (run) => {
      let cur = 0, any = false;
      for (const w of run.toLowerCase().split(/[\s-]+/)) {
        if (w === 'and') continue;
        if (w === 'hundred') { cur = (cur || 1) * 100; any = true; continue; }
        const v = ONES[w] != null ? ONES[w] : TENS[w]; if (v == null) return run; cur += v; any = true;
      }
      return any ? String(cur) : run;
    });
  };
  // a fraction is stated to one decimal ("a third" = 33.3%) and quoted rounded ("33%"): both are the source's figure
  const ROUNDED = { 33.3: 33, 66.7: 67 };
  const valueSetOf = (t) => { const s = new Set(); for (const f of figures(t)) { s.add(f.v); if (f.pct && ROUNDED[f.v] != null) s.add(ROUNDED[f.v]); } return s; };
  const PCT_NEAR = /%|\bper\s?cent\b|\bpercent(?:age)?\b/i;
  const cutPct = (f, t) => {
    if (!f || !f.pct || f.year) return false;
    const n = String(f.n).replace(/[.]/g, '\\.');
    const re = new RegExp('(^|[^\\d.,$€£₹])' + n + '\\s*(?:\\.{3}|…|$)', 'g');
    for (const m of t.matchAll(re)) { const at = m.index + m[1].length; if (PCT_NEAR.test(t.slice(Math.max(0, at - 240), at))) return true; }
    return false;
  };
  // the magnitude is part of the figure: "AED 50 million" in the source does not vouch for "AED 50bn" in the draft
  const valueSet = (text) => valueSetOf(spelled(text));
  const hasFigure = (f, text) => { if (!f) return false; const t = spelled(text); return valueSetOf(t).has(f.v) || cutPct(f, t); };
  // an excerpt the run read was cut short (a search snippet: "…", "...", "Read more"): a figure missing from it is "not in the excerpt
  // the run read", never "the source does not carry it" — the page itself was never read in full.
  const cutShort = (text) => /\.{3}|…|\bread more\b/i.test(String(text == null ? '' : text));
  return { TRACK, clean, key, host, tier, TIERS, strong, figures, valueOf, valueSet, hasFigure, spelled, cutShort, FIG_RE };
})();
// Verified facts: statistics from a second live search ("<keyword> statistics <year>"), kept only with their source URL,
// so the writer can cite real numbers instead of inventing them or hiding behind [Statistic].
// 2026-10-11 (FIX_PLAN G4): the URL is stored without its tracking parameters (a Statista link kept `?srsltid=` live), the source's
// quality is recorded (primary / research / press / vendor documentation / weak), and `text` keeps everything we actually read from the
// source — the snippet plus its title — because Content QA later looks up every figure of the draft in exactly that text.
const prev = $('Analyze Competitor Pages').first().json;
// R18 (2026-10-14): the facts search gets the same gate as the keyword's SERP. When both attempts fail, "no statistics were found"
// would be a lie — nothing was searched — so the run carries `facts_evidence.unavailable` instead.
const factsStats = RT.one((() => { try { return $('Facts SERP').first().json; } catch (e) { return $input.first().json || {}; } })(),
                          (() => { try { return $('Facts SERP (Retry)').first().json; } catch (e) { return null; } })());
const facts_evidence = RT.evidence('the statistics search for this keyword', factsStats, { unit: 'search' });
const res = factsStats.answers[0] || $input.first().json || {};
const items = res.tasks?.[0]?.result?.[0]?.items || [];
const AUTH = /\.(gov|edu|int|mil)(\.|$)|\b(statista|gartner|forrester|idc\.com|mckinsey|deloitte|pwc|kpmg|ey\.com|accenture|bcg\.com|bain\.com|hbr\.org|forbes|reuters|bloomberg|bbc|nytimes|economist|ft\.com|who\.int|oecd|worldbank|imf\.org|un\.org|europa\.eu|ibisworld|grandviewresearch|marketsandmarkets|mordorintelligence|techtarget|g2\.com|capterra|clutch\.co|semrush|ahrefs|hubspot|salesforce|microsoft|google|adobe|zendesk|shopify|stripe|nielsen|pewresearch|census|gov\.uk|nhs\.uk)\b/i;
const facts = [], paa = [];
for (const it of items) {
  if (it.type === 'people_also_ask') { (it.items || []).forEach(q => { const t = q.title || q.question; if (t) paa.push(t); }); continue; }
  if (it.type !== 'organic') continue;
  const snippet = String(it.description || '').replace(/\s+/g, ' ').trim();
  if (!/\d/.test(snippet) || snippet.length < 40) continue;
  const dom = String(it.domain || '').replace(/^www\./, '');
  if (/(^|\.)(youtube|linkedin|facebook|reddit|quora|medium|pinterest|tiktok|instagram|x|twitter|slideshare|scribd|coursera|udemy)\.(com|org|net)$/.test(dom)) continue;   // social/video: not citable sources
  const url = SRC.clean(String(it.url || ''));
  const title = String(it.title || '').slice(0, 120);
  facts.push({ claim: snippet.slice(0, 300), text: (title + ' — ' + snippet).slice(0, 700), source: dom, url, title,
    authority: (AUTH.test(dom) || AUTH.test(url)) ? 'high' : 'medium', tier: SRC.tier(url), year: (snippet.match(/\b(20[12]\d)\b/) || [])[1] || null });
}
facts.sort((a, b) => (b.authority === 'high') - (a.authority === 'high') || (b.year || 0) - (a.year || 0));
// at most one weak source per domain reaches the writer: a vendor or agency blog cited three times was the live defect (exec 365)
const weakSeen = new Set();
const kept = facts.filter(f => { if (f.tier !== 'weak') return true; if (weakSeen.has(f.source)) return false; weakSeen.add(f.source); return true; });
const known = new Set((prev.serp_features || {}).people_also_ask || []);
return [{ json: { ...prev, facts: kept.slice(0, 10), facts_found: facts.length, facts_evidence,
  facts_note: 'Search snippets with their source URL. A figure may be quoted only as written and only with its source link: every figure in the draft is looked up in this text, and one that is not here is marked [Confirm: …] for review.',
  extra_questions: paa.filter(q => !known.has(q)).slice(0, 8) } }];

parameters.text:
=You are a demanding editor-in-chief and SEO lead reviewing a draft before it goes to a client. Judge it against the brief and the quality bar below. Be concrete: quote the exact sentence or heading for every problem, and give the fix.

TARGET
Keyword: {{ $('Parse Brief').first().json.keyword }} · Page type: {{ $('Parse Brief').first().json.page_type }} · Audience: {{ $('Parse Brief').first().json.content_brief.target_audience || $('Parse Brief').first().json.audience }} · Goal: {{ $('Parse Brief').first().json.goal || 'leads' }} · Target words: {{ $('Parse Brief').first().json.content_brief.target_word_count }}

BRIEF ESSENTIALS
Unique angle: {{ $('Parse Brief').first().json.content_brief.unique_angle }}
Information gain items: {{ ($('Parse Brief').first().json.content_brief.information_gain || []).join(' · ') }}
Objections to answer: {{ ($('Parse Brief').first().json.content_brief.objections || []).join(' · ') }}
Snippet targets: {{ ($('Parse Brief').first().json.content_brief.snippet_targets || []).map(s => s.question).join(' | ') }}
Terms to use: {{ ($('Parse Brief').first().json.content_brief.terms_to_use || []).map(t => t.term).join(', ') }}
Allowed external facts: {{ ($('Parse Brief').first().json.content_brief.evidence_plan || []).map(e => e.fact).join(' | ') || 'none' }}
Client facts (true, may be stated): {{ [...($('Parse Brief').first().json.content_brief.client_facts || []), $('Parse Brief').first().json.business_facts || '', $('Parse Brief').first().json.case_facts_text || ''].filter(Boolean).join(' | ') || 'none' }}
Facts from the client's own website ({{ (($('Parse Brief').first().json.site_description || {}).pages_read || []).length || 1 }} page(s) read — its services, sections and headings; all of this is true and may be stated): {{ ((($('Parse Brief').first().json.site_description || {}).site_facts) || ($('Parse Brief').first().json.site_description || {}).products_or_services || []).join(' · ') || 'none read' }}

{{ ($('Parse Brief').first().json.page_contract || {}).text || '' }}

QUALITY BAR
1. Specificity: examples, numbers with linked sources, decision rules, steps — not generic advice.
2. Originality and information gain: every information-gain item is covered fully; the page says something competitors do not.
3. Audience fit: speaks to the stated audience and answers their objections.
4. Trust: no unsupported claims or invented numbers; external numbers carry a source link; client facts are used correctly; no bracket of any kind in the page (a missing fact is written around, never left as [Price] or [Confirm: ...]). Anything that appears in the client facts or in the facts from the client's own website above is TRUE: never call it invented, made up or unsupported, whatever wording the draft uses for it. For anything else that cannot be checked, the word is "unverified" — say what would verify it (a source link) or how to say it without the claim; never "invented", and never suggest a bracket or a placeholder as the fix.
5. Readability and voice: plain words, varied sentence length, active voice, no filler, none of the banned phrases (delve, unlock, seamless, robust, leverage, cutting-edge, game-changer, elevate, empower, crucial, paramount, realm, embark, foster, streamline, synergy, holistic, best-in-class, world-class, state-of-the-art, top-notch, one-stop shop, "in today's fast-paced world", "ever-evolving", "it's important to note", "in conclusion", "when it comes to", "a wide range of").
6. Search fit: matches the intent, at least three headings phrased as the questions buyers ask and answered directly in the 40-60 words under them (no "Frequently Asked Questions" block and no Q1:/A1: list — Google stopped showing FAQ rich results in May 2026), terms used naturally, primary keyword placed correctly without stuffing, internal links only to allowed URLs and never to a page that is not published yet.
7. Structure: follows the outline order and target lengths, comparison table present, CTA last, meta title ≤60 and description 120-155 characters.

SOURCE QUALITY — what a citation is worth, best first. Judge every external link against this list and say so in "problems" when the draft falls short.
1. Primary: a government, regulator, standards body or official statistics page (.gov, .gov.<country>, .edu, europa.eu, iso.org, w3.org, peppol.org, u.ae, the WHO / OECD / World Bank / IMF / UN).
2. Research: a named research house publishing its own data (Statista, Gartner, Forrester, IDC, McKinsey, Deloitte, PwC, KPMG, EY, BCG, Bain, Pew, Nielsen, Grand View, MarketsandMarkets).
3. Major press: Reuters, Bloomberg, the BBC, the Financial Times, the Wall Street Journal, the New York Times, The Economist, AP, CNBC, Khaleej Times, The National, Gulf News, Zawya.
4. Vendor documentation: a product's own documentation or release notes (Microsoft Learn, Oracle, SAP, Odoo, Zoho docs) — fine for how the product works, never for a market figure.
5. Weak: everything else — a vendor's or agency's blog post, a listicle, an unknown site. The page may cite at most ONE page per weak domain; a second citation of the same weak domain is a high-severity problem, and so is a market or compliance figure whose only source is a weak page.
Also flag: a figure that does not appear in the source it links to, a link with tracking parameters (utm_*, srsltid, gclid, fbclid), and a link to a page of this site that is not published yet.

DRAFT
{{ $json.output }}

Return ONLY valid JSON (no markdown, no backticks):
{
  "score": 0-100,
  "verdict": "publish | revise | rewrite",
  "strengths": ["2-4 specific strengths"],
  "problems": [{ "severity": "high | medium | low", "location": "quoted text or heading (max 15 words)", "issue": "what is wrong", "fix": "exactly what to write or change" }],
  "banned_phrases_found": ["phrases from the banned list that appear"],
  "unsupported_claims": ["quoted claims with numbers or superlatives that have no source and no match in the client facts or the website facts above — these are unverified, not invented"],
  "missing_brief_items": ["outline sections, information-gain items, snippet targets or terms that are missing"],
  "revision_instructions": "Numbered, specific instructions the editor can apply without re-reading this review (max 12 items)"
}
List at most 12 problems, most damaging first. Every fix you give follows THE PAGE CONTRACT above: never ask for a process, steps, a deliverable or a stance in the business's voice that the client facts do not state (ask for it as advice to the reader instead), never ask the page to grow past its length band, and say "advice" for anything that is not about facts, trust or the law. Score 85+ only if you would publish it under your own name.

parameters.jsCode:
// Accepts an object (from the Structured Output Parser) or a string; attaches the critique to the draft for Content QA.
const parseAgentJson = (raw) => {
  if (raw && typeof raw === 'object') return raw;
  let s = String(raw || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
};
const prev = $('Parse Brief').first().json;
const draft = $('Copywriter').first().json.output;
let cr = parseAgentJson($input.first().json.output);
if (!cr || typeof cr !== 'object') cr = { score: null, verdict: 'unknown', problems: [], revision_instructions: '', strengths: [], banned_phrases_found: [], unsupported_claims: [], missing_brief_items: [], parse_failed: true };
cr.problems = Array.isArray(cr.problems) ? cr.problems.slice(0, 12) : [];

// ---- D22 (2026-10-11, system review FIX_PLAN): a claim found on the client's own website is not "invented" ----
// Live (exec 365) the critic called Tech&'s real delivery stages ("Assess & Envision", "Run & Optimise") invented, because only the homepage
// was ever read. The site facts (services, sections and headings of every page the describer read, kept in site_description by Parse
// Description) are checked here as well as in the prompt: a claim that quotes something the website itself says is dropped from
// unsupported_claims and from the problems, and everything the critic still calls invented is renamed "unverified" — the honest word for a
// statement nobody has checked.
const sd = prev.site_description || {};
const norm = (s) => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
const facts = [...(sd.site_facts || []), ...(sd.products_or_services || []), ...(sd.unique_selling_points || []), sd.business_description, sd.one_line_summary,
  ...(prev.content_brief && prev.content_brief.client_facts || []), prev.business_facts, prev.case_facts_text, prev.business]
  .map(norm).filter(f => f.length >= 4);
const factBlob = ' ' + facts.join(' || ') + ' ';
const figures = (s) => (String(s == null ? '' : s).match(/\d[\d,.]*/g) || []).map(x => x.replace(/[,.]+$/, ''));
const onSite = (q) => {
  const t = norm(q); if (t.length < 4) return false;
  if (figures(q).some(f => !factBlob.includes(f))) return false;                            // a figure the website never states is not "on the site", whatever words surround it
  if (factBlob.includes(' ' + t + ' ')) return true;                                        // the claim is one of the facts
  return facts.some(f => f.split(' ').length >= 2 && (t.includes(f) || (t.split(' ').length >= 2 && f.includes(t))));   // a 2+ word fact inside the claim, or the other way round
};
const unverified = (s) => String(s == null ? '' : s).replace(/\binvent(ed|s|ing)?\b/gi, 'unverified').replace(/\bmade[- ]up\b/gi, 'unverified').replace(/\bfabricat(ed|es|ing|ion)\b/gi, 'unverified');
const claims = Array.isArray(cr.unsupported_claims) ? cr.unsupported_claims.map(c => (c && typeof c === 'object' ? JSON.stringify(c) : String(c))) : [];
cr.claims_on_site = claims.filter(onSite);
cr.unsupported_claims = claims.filter(c => !onSite(c));
const INVENTION = /\binvent|made[- ]up|fabricat|unsupported|no source|not supported|unsubstantiated\b/i;
cr.problems = cr.problems.filter(p => !(p && typeof p === 'object' && INVENTION.test(String(p.issue || '')) && (onSite(p.location) || onSite(p.issue))))
  .map(p => (p && typeof p === 'object' ? { ...p, issue: unverified(p.issue), fix: unverified(p.fix) } : p));
cr.revision_instructions = unverified(cr.revision_instructions);
