const competitor_questions = [...new Set(competitors.flatMap(c => c.headings.map(h => h.replace(/^H\d: /, '')).filter(h => /\?$/.test(h) || /^(how|what|why|when|which|where|who|can|do|does|is|are|should)\b/i.test(h))))].slice(0, 15);
