  "unique_angle": "",
  "outline": [
    { "h2": "", "purpose": "Why this section exists and what the reader can do after it", "key_points": ["", ""], "h3s": ["optional sub-headings"], "target_words": 0, "format": "prose | steps | checklist | table | comparison | example", "evidence": ["which verified fact or client fact to use here, or 'none' (then the section carries no number)"], "link_to": "hub pages only: the URL of the cluster page this section summarises and links to, else empty" }
  ],
