// No property id = no request, and *GA4 Key Events* says so; the fix list is then weighted by clicks and impressions, and says that.
const prev = $input.first().json || {};
let base = {}; try { base = $('Check Crawl').first().json || {}; } catch (e) {}
const pid = String(prev.ga4_property_id || base.ga4_property_id || '').replace(/^properties\//, '').replace(/[^0-9]/g, '').slice(0, 16);
if (!pid) return [{ json: { skip: true, reason: 'no GA4 property id came with this audit request, so the fix list is weighted by Search Console clicks and impressions' } }];
const day = (d) => d.toISOString().slice(0, 10);
const end = new Date(Date.now() - 86400000), start = new Date(end.getTime() - 27 * 86400000);
const ORGANIC = { filter: { fieldName: 'sessionDefaultChannelGroup', stringFilter: { matchType: 'EXACT', value: 'Organic Search' } } };
return [{ json: { skip: false, ga4_property_id: pid, period: { start: day(start), end: day(end), days: 28 },
  url: 'https://analyticsdata.googleapis.com/v1beta/properties/' + pid + ':runReport',
  body: { dateRanges: [{ startDate: day(start), endDate: day(end) }], dimensions: [{ name: 'landingPage' }], metrics: [{ name: 'keyEvents' }, { name: 'sessions' }],
    dimensionFilter: ORGANIC, orderBys: [{ metric: { metricName: 'keyEvents' }, desc: true }], limit: 250, metricAggregations: ['TOTAL'] } } }];

// B5-12: GA4's answer (key events and sessions per organic landing page, 28 days) as the `ga4_key_events` block the impact weight reads.
// connected:false always carries the reason; zero key events across the whole property is "none configured or none recorded", which is
// NOT usable as a weight (every page would be worth zero), so the weight falls back to clicks and impressions and says so.
let audit = {}; try { audit = $('Not Crawled Check').first().json || {}; } catch (e) {}
let plan = {}; try { plan = $('GA4 Key Events Plan').first().json || {}; } catch (e) {}
const out = (block) => [{ json: { ...audit, ga4_key_events: block } }];
if (plan.skip !== false) return out({ connected: false, reason: plan.reason || 'not requested' });
const r = $input.first().json || {};
const gErr = (x) => { if (!x) return 'no response'; const e = x.error; if (!e) return null; if (typeof e === 'string') return e.slice(0, 200); const m = (e.message || e.description || (e.error && e.error.message) || ''); return String(m || JSON.stringify(e)).slice(0, 200); };
const err = gErr(r);
if (err) return out({ connected: false, property: plan.ga4_property_id, reason: 'GA4 answered: ' + err + ' (the service account needs Viewer on the property)' });
const rows = Array.isArray(r.rows) ? r.rows : [];
const by = new Map();
const pathOf = (u) => String(u || '').replace(/^https?:\/\/[^\/]+/, '').replace(/[?#].*$/, '').replace(/(.)\/$/, '$1') || '/';
for (const row of rows) {
  const p = pathOf(((row.dimensionValues || [])[0] || {}).value);
  const ke = Number(((row.metricValues || [])[0] || {}).value) || 0, se = Number(((row.metricValues || [])[1] || {}).value) || 0;
  const cur = by.get(p) || [p, 0, 0]; cur[1] += ke; cur[2] += se; by.set(p, cur);
}
const list = [...by.values()].sort((a, b) => b[1] - a[1]);
const tot = (r.totals && r.totals[0] && r.totals[0].metricValues) || [];
const totalKe = tot.length ? Number(tot[0].value) || 0 : list.reduce((n, x) => n + x[1], 0);
const totalSe = tot.length ? Number(tot[1].value) || 0 : list.reduce((n, x) => n + x[2], 0);
const complete = (Number(r.rowCount) || rows.length) <= rows.length;
const block = { connected: true, property: plan.ga4_property_id, period: plan.period, rows: list.slice(0, 250), rows_complete: complete,
  total_key_events: totalKe, total_sessions: totalSe, basis: 'GA4 key events on organic-search landing pages, last 28 complete days' };
if (!totalKe) return out({ ...block, usable: false, reason: 'GA4 recorded no key events from organic search in the last 28 days (none configured, or none happened), so they cannot rank the findings' });
return out({ ...block, usable: true });

// ---- source kit (G4, 2026-10-11; inlined through the __SOURCES__ marker): what a citation is worth, what a figure says, and clean links.
// The 2026-10-11 review found a page that cited one vendor blog (trangotech.com) three times and kept Google's `?srsltid=` on a Statista
// link, with no check that the numbers in the copy are the numbers the source actually carries (RESULTS.md §2.4, exec 365).
//   SRC.clean(url)      strips the tracking parameters (utm_*, srsltid, gclid, fbclid …) from any link, in the copy and in the schema.
//   SRC.tier(url)       primary (government, standards, official statistics) > research > press > vendor documentation > weak.
//                       A vendor's blog or "resources" post is weak, like any unknown site; at most one citation per weak domain.
//   SRC.figures(text)   every figure with its position: percentages, currency amounts, magnitudes (k / m / bn), years, counts >= 1,000.
//                       Small bare numbers ("3 steps", "8 phases") are not claims and are never checked.
//   SRC.hasFigure(f, t) the same figure in the source text, in any format: separators, "m" / "million", "AED 50m" / "AED 50 million".
// Regex only: the n8n Code sandbox has no URL constructor.
const SRC = (() => {
  const TRACK = /^(?:utm_[a-z0-9_]*|srsltid|gclid|gbraid|wbraid|dclid|fbclid|msclkid|yclid|twclid|ttclid|igshid|mc_cid|mc_eid|_hsenc|_hsmi|hsa_[a-z0-9_]*|s_kwcid|vero_id|oly_enc_id|cmpid|mkt_tok|spm|scid|ref_src|pk_campaign|pk_kwd|piwik_campaign|at_medium|at_campaign)$/i;
  const host = (u) => { const m = String(u == null ? '' : u).trim().match(/^https?:\/\/(?:[^@\/?#]*@)?([^\/?#:]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };
  const clean = (u) => {
    const s = String(u == null ? '' : u).trim();
