const homeOnFile = SM.pages(pm).find(p => p && p.url && SM.helpers.bare(SM.helpers.hostOf(p.url) || '') === own && SM.helpers.pathOf(p.url).replace(/[?#].*$/, '').replace(/\/+$/, '') === '' && String(p.title || '').trim());
